'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {prepareHandoffDecision,handoffDecisionArgs,readHandoffDecisionReceipt,readHandoffDecisionStatus,loadHandoffDecision,saveHandoffDecision,clearHandoffDecision,type Handoff,type HandoffScope,type HandoffDecision} from '@/lib/cashier-handoff';
export function CashierHandoffDecision({scope,handoff,onSaved}:{scope:HandoffScope;handoff:Handoff;onSaved:()=>void}){
 const [pending,setPending]=useState<HandoffDecision|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{setPending(loadHandoffDecision(sessionStorage,scope,handoff.id))}catch(e){setError(e instanceof Error?e.message:'Unable to recover handoff.')}return()=>{alive.current=false}},[scope.tenant,scope.property,scope.actor,handoff.id]);
 async function run(request:HandoffDecision,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{
  const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen handoffs.');if(!alive.current)return;saveHandoffDecision(sessionStorage,request);setPending(request);
  const result=await hotelRpc(status?'cashier_handoff_status':'resolve_cashier_handoff',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:request.request,p_kind:'resolve'}:handoffDecisionArgs(request));
  const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover after signing in.');if(!alive.current)return;
  if(status){if(!readHandoffDecisionStatus(result,request)){if(handoff.outcome!=='pending'&&handoff.id===request.handoff&&handoff.amount===request.amount&&(handoff.sender===scope.actor||handoff.receiver===scope.actor)){clearHandoffDecision(sessionStorage,request);setPending(null);setMessage('This handoff was already '+handoff.outcome+'. Your pending decision was not recorded and has been cleared.');return}setMessage('No saved decision found. Refresh cash handoffs to check for another decision, or retry the original request.');return}}else readHandoffDecisionReceipt(result,request);
  clearHandoffDecision(sessionStorage,request);setPending(null);setMessage('Handoff decision saved.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Decision interrupted. Check its saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section>{pending?<><p>Pending decision: {pending.outcome} — {pending.reason}</p><button disabled={busy} onClick={()=>void run(pending)}>Retry handoff decision</button><button disabled={busy} onClick={()=>void run(pending,true)}>Check handoff decision</button></>:handoff.outcome==='pending'&&<form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);void run(prepareHandoffDecision(scope,crypto.randomUUID(),handoff,String(f.get('outcome')),String(f.get('reason')).trim()))}catch(e){setError(e instanceof Error?e.message:'Review handoff details.')}}}><fieldset disabled={busy}><label>Handoff decision<select name="outcome">{scope.actor===handoff.sender?<option value="cancelled">Cancel handoff</option>:<><option value="accepted">Accept counted cash</option><option value="rejected">Reject handoff</option></>}</select></label><label>Decision explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm this decision. Acceptance confirms receipt of the full recorded cash amount.</label><button>Save handoff decision</button></fieldset></form>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}